import {CAMPUS_NODES,CAMPUS_ROADS} from './campus-catalog.js';
import {createRound2} from './round2-ui.js';
import {STORE,empty,validate,timerRemaining,timerToggle,transition,canDisplay,enroll} from './core.js';
import {places,clubs,events,states} from './data.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db;try{db=validate(JSON.parse(localStorage.getItem(STORE)))}catch{db=empty()}
let route='world',scene=null,sceneSession=0,filter='全部',search='',sound=null,installPrompt=null,toastTimer=null,atlasFilter='全部',atlasSearch='',atlasSelected='beimen';
const iconPaths={arrow:'M7 17 17 7M7 7h10v10',sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6 7 7m10 10 1.4 1.4M5.6 18.4 7 17M17 7l1.4-1.4M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',moon:'M20 15a8 8 0 0 1-11-11 8 8 0 1 0 11 11',leaf:'M20 4C9 2 3 7 5 15s16 5 15-11ZM5 19 15 9',book:'M3 5h6l3 2 3-2h6v14h-6l-3 2-3-2H3ZM12 7v14',map:'m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3ZM9 3v15m6-12v15',grid:'M4 4h6v6H4ZM14 4h6v6h-6ZM4 14h6v6H4ZM14 14h6v6h-6Z',camera:'M3 7h4l2-3h6l2 3h4v13H3ZM16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',volume:'M4 9h4l5-5v16l-5-5H4ZM17 8q5 4 0 8',mute:'M4 9h4l5-5v16l-5-5H4ZM17 9l5 6m0-6-5 6',clock:'M12 7v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',star:'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z',plus:'M12 5v14M5 12h14',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',chevron:'m9 5 7 7-7 7',search:'M16 16l5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',box:'m12 3 9 5-9 5-9-5ZM3 8v9l9 5 9-5V8M12 13v9',music:'M9 17V5l11-2v12M9 17a3 3 0 1 1-3-3h3m11 1a3 3 0 1 1-3-3h3',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',play:'m8 4 12 8-12 8Z',pause:'M8 5v14M16 5v14',reset:'M4 9a8 8 0 1 1 0 6M4 3v6h6',pin:'M12 22s8-8 8-14a8 8 0 0 0-16 0c0 6 8 14 8 14ZM15 8a3 3 0 1 1-6 0 3 3 0 0 1 6 0',folder:'M3 5h7l2 3h9v12H3Z',edit:'m4 16 12-12 4 4L8 20H4ZM13 7l4 4',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6ZM8 12l3 3 5-6'};
const I=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.star}"/></svg>`;
const btn=(label,action,cls='',icon='')=>`<button class="btn ${cls}" data-action="${action}">${icon?I(icon):''}${label}</button>`;
const arrow=()=>I('arrow',18);
const small=(s)=>`<span class="eyebrow">${s}</span>`;
function save(){try{localStorage.setItem(STORE,JSON.stringify(db));return true}catch{toast('浏览器无法保存。当前内容暂留内存，请导出备份。');return false}}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3200)}
function header(){const group=['study','assignments','shelf','paper','resources','windowsill'].includes(route)?'study':['homework','teach','desk','lesson','activities','classroom'].includes(route)?'homework':['club','constellation','works','moderation'].includes(route)?'club':'world';return `<header class="topbar"><a class="brand" href="#world" aria-label="HAIZ WORLD 首页"><span class="brand-symbol">${I('box',25)}</span><span>haiz<span class="brand-dot">.</span>space<small>A SCHOOL, MANY WORLDS</small></span></a><nav class="main-nav" aria-label="主导航">${[['study','我的自习室','book'],['homework','教师与教室','grid'],['world','校园世界','leaf'],['club','社团创作','star']].map(([r,l,i])=>`<a href="#${r}" ${group===r?'aria-current="page"':''}>${I(i,16)}<span>${l}</span></a>`).join('')}</nav><div class="header-actions"><span class="demo-label"><i></i> DEMO</span><button class="icon-btn" data-action="about" aria-label="关于与演示设置">${I('grid')}</button></div></header>`}
function footer(){return `<footer class="footer"><a class="brand footer-brand" href="#world">haiz.space</a><span>一所学校，许多世界。<br><small>非官方概念演示 · 无真实校内业务数据</small></span><div><a href="../journal.html">校园旧站 ${arrow()}</a><button data-action="sources">来源与许可</button><button data-action="install">加入主屏幕</button></div><small>© 2026 HAIZ WORLD</small></footer>`}
function moodButtons(compact=false){return `<div class="segmented mood-switch ${compact?'compact':''}" aria-label="概念光照">${[['morning','晨光','sun'],['shade','树影','leaf'],['rain','雨后','moon'],['sunset','日落','sun']].map(([id,label,ico])=>`<button data-action="mood:${id}" aria-pressed="${db.prefs.mood===id}">${I(ico,16)}<span>${label}</span></button>`).join('')}</div>`}
function world(){return `<main id="main" class="world-page"><div class="world-subnav"><span>${small('01 / THE PUBLIC WORLD')}<span class="subnav-note">在这里，把脚步放慢一点。</span></span><div><a href="#memory">校园记忆</a><a href="#study">课间窗台</a><a href="#atlas">${I('map',16)} 全校地图 · 34 地点</a></div></div><section class="hero" data-mood="${db.prefs.mood}"><img class="hero-image" src="assets/campus.webp" alt="日落中的绿瓦建筑、榄仁树与水面；生成式概念美术，非实景照片" fetchpriority="high"><div class="hero-shade"></div><div class="hero-top"><span class="glass-tag"><span class="dot"></span> HAINAN · A CAMPUS REIMAGINED</span><span class="hero-concept">体素校园 · 概念美术</span></div><div class="hero-copy">${small('A PLACE TO GET LOST, OR FOUND')}<h1>HAIZ<br><em>WORLD.</em></h1><p class="hero-chinese">这一次，走进整座校园。</p><p class="hero-description">在树荫下停留，在光里漫游。<br>熟悉的校园，还有新的故事。</p><div class="hero-actions"><a class="btn cream" href="#walk">${I('play',17)} 进入校园 <span>→</span></a><a class="quiet-link" href="#study">安静自习一会儿 ${arrow()}</a></div></div><div class="hero-weather">${I(db.prefs.mood==='rain'?'moon':'sun',38)}<span class="weather-name">${{morning:'清晨时分',shade:'午后树影',rain:'雨后的光',sunset:'日落时分',night:'夜间窗灯'}[db.prefs.mood]}</span><span class="weather-caption">概念光照 · 非实时天气</span><div class="weather-line"></div><p>风穿过树梢，<br>也吹向了你。</p></div><div class="hero-bottom">${moodButtons()}<button class="sound-toggle" data-action="sound" aria-pressed="${!!sound}">${I(sound?'volume':'mute',17)} <span>${sound?'合成风声已开启':'听一会儿风'}</span></button><span class="hero-index"><b>34</b> / CAMPUS <span>第一人称 · 16 间开放教室</span></span></div></section><section class="round2-entry"><div><h2>不用手机，也能参与校园。</h2><p>教室里的公共屏，和回家后能接回思路的自习室。</p></div><div class="row-actions"><a class="btn cream" href="#classroom">打开教室屏 ↗</a><a class="btn outline" href="#study">接回我的思路 ↗</a></div></section><section class="places-section"><div class="section-heading"><div>${small('TAKE THE LONG WAY HOME')}<h2>总有一处，值得停留。</h2></div><a class="text-link" href="#memory">打开校园记忆 ${arrow()}</a></div><div class="place-grid">${places.map(p=>`<button class="place-card" data-action="place:${p.id}"><div class="place-image" style="background-position:${p.position}"><span class="place-number">${p.number}</span><span class="circle-arrow">${arrow()}</span></div><div class="place-caption"><div><h3>${p.name}</h3><p>${p.line}</p></div><span>${p.tag}</span></div></button>`).join('')}</div></section><section class="world-feature"><div class="focus-teaser"><div>${small('A QUIET CORNER')}<h2>把这一刻，留给自己。</h2><p>一方窗景，一张便笺。<br>不用赶路，也很好。</p><a class="text-link" href="#study">去课间窗台 ${arrow()}</a></div><div class="clock-art"><span>FOCUS</span><strong data-timer>25:00</strong><small>只在你的设备上计时</small></div></div><div class="exhibit-teaser">${small('MADE BY US')}<h2>校园因创作，慢慢生长。</h2><p>一场活动、一件作品，经过作者选择与审核，<br>成为你漫游时偶然遇见的一段故事。</p><a href="#club" class="text-link">从一个兴趣开始 ${arrow()}</a></div></section>${exhibits()}</main>`}
function exhibits(){const works=db.works.filter(canDisplay);return works.length?`<section class="exhibits"><div class="section-heading"><h2>砚池边的数字展签</h2><span class="badge">仅本机 DEMO</span></div><div class="work-grid">${works.map(w=>`<article class="work-card">${small('STUDENT CREATION · DEMO')}<h3>${esc(w.title)}</h3><p>${esc(w.body)}</p><span>演示作者 · 砚池</span><button class="text-link" data-action="report:${w.id}">举报此演示展签</button></article>`).join('')}</div></section>`:''}
function atlasDetail(){const p=CAMPUS_NODES.find(x=>x.id===atlasSelected)||CAMPUS_NODES[0];return `<span class="eyebrow">${p.number} / ${p.category}</span><h2>${esc(p.name)}</h2><p>${esc(p.description)}</p><div class="architecture-evidence"><span>${esc(p.evidence)}</span>${p.photo?`<a href="${p.photo}" target="_blank" rel="noopener"><img src="${p.photo}" alt="${esc(p.name)}的仓库参考照片" loading="lazy"><small>查看原图 ↗</small></a>`:`<p>外形、楼层、屋顶、颜色和位置均待核对。当前体量只用于漫游定位。</p>`}</div><a class="btn primary" href="#walk?place=${p.id}">第一人称走到这里 ${arrow()}</a>${p.form==='academic'?'<small>首层想象教室可进入，上层与楼梯未开放。</small>':'<small>位置沿用旧站数据，非实地导航。宿舍等建筑仅作外观漫游。</small>'}`}
function atlasResults(){const list=CAMPUS_NODES.filter(p=>(atlasFilter==='全部'||p.category===atlasFilter)&&(!atlasSearch||p.name.includes(atlasSearch)||p.id.includes(atlasSearch.toLowerCase())));return `<p class="atlas-result-count" role="status">${list.length} / 34 个校园节点</p>${list.map(p=>`<button class="atlas-result" data-action="atlas-place:${p.id}" aria-pressed="${atlasSelected===p.id}"><span>${p.number}</span><strong>${esc(p.name)}</strong><small>${p.category} ↗</small></button>`).join('')||'<p>没有找到这个地点，换个关键词试试。</p>'}`}
function atlasUpdate(){if($('#atlas-results'))$('#atlas-results').innerHTML=atlasResults();$$('[data-action^="atlas-filter:"]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.action==='atlas-filter:'+atlasFilter)));$$('.campus-node').forEach(n=>{const p=CAMPUS_NODES.find(p=>p.id===n.dataset.node);n.classList.toggle('is-selected',p.id===atlasSelected);n.classList.toggle('is-muted',(atlasFilter!=='全部'&&p.category!==atlasFilter)||!!atlasSearch&&!p.name.includes(atlasSearch)&&!p.id.includes(atlasSearch.toLowerCase()))});if($('#atlas-detail'))$('#atlas-detail').innerHTML=atlasDetail()}
function atlas(){return `<main id="main" class="full-atlas"><div class="atlas-title"><div>${small('THE WHOLE CAMPUS / 34 PLACES')}<h1>这次，整座校园都在。</h1><p>从校门到砚池，从连廊到操场。找一个地点，再走进去。</p></div><a href="#walk" class="btn cream">直接开始行走 ${arrow()}</a></div><div class="atlas-workspace"><section class="atlas-sheet" aria-label="校园平面示意图"><div class="atlas-sheet-head"><span>HAIZ / 府城校区</span><span>上南 · 下北</span></div><svg viewBox="0 0 600 600" role="group" aria-label="可选择的 34 个校园地点"><rect width="600" height="600" fill="#e8e9d9"/>${CAMPUS_ROADS.map(r=>`<rect x="${r[0]}" y="${r[1]}" width="${r[2]}" height="${r[3]}" fill="#d2d7c6"/>`).join('')}${CAMPUS_NODES.map(p=>{const [x,y,w,h]=p.rect;return `<g class="campus-node ${p.id===atlasSelected?'is-selected':''}" data-node="${p.id}" data-action="atlas-place:${p.id}" tabindex="0" role="button" aria-label="查看${esc(p.name)}"><title>${esc(p.name)}</title><rect x="${x}" y="${y}" width="${Math.max(w,5)}" height="${Math.max(h,5)}" rx="2" fill="${p.form==='pond'?'#8eb1a6':p.category==='风景'?'#a1b28a':p.category==='运动'?'#bd9a77':'#a6b39b'}"/><circle cx="${x+w/2}" cy="${y+h/2}" r="9"/><text x="${x+w/2}" y="${y+h/2+3}">${p.number}</text></g>`}).join('')}<text x="300" y="575" text-anchor="middle" font-size="11" fill="#687c64">N / 北 · 校门入口</text></svg><div class="atlas-sheet-caption"><span>建筑轮廓与节点来自保留的校园数据</span><span>地图无需 WebGL</span></div><article id="atlas-detail" class="atlas-detail">${atlasDetail()}</article></section><aside class="atlas-directory"><label for="atlas-search">找一个熟悉的名字</label><div class="atlas-search-wrap">${I('search',18)}<input id="atlas-search" type="search" placeholder="图书馆、教学楼、食堂…" value="${esc(atlasSearch)}"></div><div class="atlas-categories">${['全部','学习','风景','生活','运动','校道'].map(c=>`<button data-action="atlas-filter:${c}" aria-pressed="${atlasFilter===c}">${c}</button>`).join('')}</div><div id="atlas-results">${atlasResults()}</div><div class="atlas-room-note"><span>16</span><div><h3>间可以走进去的教室</h3><p>四栋教学楼首层，保留桌椅、黑板与窗边。室内为创作还原。</p></div></div></aside></div><p class="atlas-legal">非学校官方地图。原 KML 与实测高度未经本轮重新核验；以校园实际安排为准。三处体素观景另见 <a href="#garden">体素庭院 ↗</a></p></main>`}
function walk(){const params=new URLSearchParams(location.hash.split('?')[1]||''),allowed=['feng','tree','pond',...CAMPUS_NODES.map(n=>n.id)],place=allowed.includes(params.get('place'))?params.get('place'):'beimen';return `<main id="main" class="campus-world"><header class="campus-world-bar"><a href="#world" class="campus-home">HAIZ <span>WORLD</span></a><span>34 个节点 · 16 间开放教室 · 第一人称</span><nav><a href="#atlas">全校地图</a><a href="#garden">庭院</a><a href="#study">去自习</a><button data-action="campus-fullscreen" aria-label="全屏校园">${I('box',18)} 全屏</button></nav></header><iframe id="full-campus" src="campus.html?enter=gate&place=${place}${params.has('atlas')?'&atlas=1':''}${params.get('quality')==='low'?'&quality=low':''}" title="完整校园：WASD 行走，鼠标或触屏环顾，M 地图，Esc 暂停" allow="fullscreen" allowfullscreen></iframe><div class="campus-world-footer"><span>校园与室内是近似模型 · 非实地导航</span><a href="campus.html?enter=gate" target="_blank" rel="noopener">独立窗口打开 ↗</a></div></main>`}
function garden(){return `<main id="main" class="walk-page"><div class="page-top"><div>${small('THE CAMPUS, AT YOUR PACE')}<h1>在体素庭院，停留片刻。</h1></div><a class="text-link" href="#world">返回世界首页 ↗</a></div><section class="walk-stage" data-mood="${db.prefs.mood}"><img src="assets/campus.webp" class="walk-fallback" alt="体素校园概念静态画面"><div id="canvas-host" tabindex="0" aria-label="体素校园 3D。拖动旋转，滚轮缩放，方向键调整视角；也可使用下方地点按钮。"></div><div class="walk-top"><span class="glass-tag" id="render-status">正在准备体素小景…</span><span class="glass-tag">布局为概念示意</span></div><div class="walk-bottom"><div>${small('YOU ARE HERE')}<h2 id="location-name">凤栖堂</h2><span>拖动环顾 · 滚轮缩放 · 方向键移动视角</span></div><div class="walk-tools"><button class="icon-btn" data-action="snapshot" aria-label="下载当前 3D 画面">${I('camera')}</button><button class="icon-btn" data-action="bookmark" aria-label="保存当前机位">${I('pin')}</button><button class="icon-btn" data-action="map" aria-label="打开二维地图">${I('map')}</button></div></div></section><div class="walk-controlbar"><div class="segmented"><button data-action="walkmode:walk" aria-pressed="true">${I('leaf',16)} 散步</button><button data-action="walkmode:view" aria-pressed="false">${I('sun',16)} 观景</button><a href="#study">${I('book',16)} 自习</a></div>${moodButtons(true)}<label class="quality-label">画质 <select id="quality" aria-label="画面精度">${[['cinematic','电影感'],['balanced','平衡'],['low','低功耗']].map(([v,t])=>`<option value="${v}" ${db.prefs.quality===v?'selected':''}>${t}</option>`).join('')}</select></label><button class="text-link" data-action="pause" aria-pressed="false">${I('pause',16)} 暂停动态</button><button class="text-link" data-action="static">静态风景</button></div><div class="walk-locations">${places.map(p=>`<button data-action="goto:${p.id}"><span>${p.number}</span><div><h3>${p.name}</h3><p>${p.tag}</p></div>${arrow()}</button>`).join('')}</div><div class="walk-note"><p>独立体素小景 · 与首屏概念美术分开展示。建筑比例与周边布局为艺术推演。</p><a href="#walk">进入完整校园 · 第一人称 ${arrow()}</a><button data-action="bookmarks">已保存机位 (${db.bookmarks.length})</button></div>${exhibits()}</main>`}
function windowsill(){return `<main id="main" class="study-page"><div class="page-top"><div>${small('THE WINDOWSILL / 课间窗台')}<h1>今天，慢慢来也可以。</h1></div><a class="text-link" href="room/index.html">完整课间窗台 ${arrow()}</a></div><div class="study-grid"><section class="study-view" data-room-mood="night"><img src="room/scene-preview.jpg" alt="保留的课间窗台三维场景预览，想象中的书桌与窗景"><div class="study-shade"></div><div class="study-title">${small('A ROOM OF YOUR OWN')}<h2>窗外有雨，<br>心里有光。</h2><span>想象窗景 · 非校园实拍</span></div><button class="btn cream study-enter" data-action="room">${I('play',16)} 走近窗台</button><div class="room-frame" id="room-frame"></div><div class="room-loading" id="room-loading" hidden>正在准备独立窗台…<button data-action="room-back">返回静态窗景</button></div><div class="room-controls"><button data-action="room-mood:rainnight" aria-pressed="true">雨夜</button><button data-action="room-mood:dusk" aria-pressed="false">晚霞</button><button data-action="room-pause" aria-pressed="false">暂停</button><button data-action="room-back">收起</button></div></section><aside class="study-panel"><div class="section-heading">${small('JUST ONE THING')} ${I('moon')}</div><h2>专注这一刻。</h2><p class="muted">没有排名，没有打卡。只做你想做的事。</p><div class="timer-ring"><span data-timer>25:00</span><small id="timer-state">给自己一点不被打扰的时间</small></div><div class="segmented timer-presets">${[[1500,'25 分钟'],[3000,'50 分钟'],[300,'休息 5 分钟']].map(([s,label])=>`<button data-action="duration:${s}" aria-pressed="${db.timer.duration===s}">${label}</button>`).join('')}</div><div class="timer-actions">${btn('开始专注','timer','primary','play')}${btn('重置','timer-reset','outline','reset')}</div><div class="note-heading"><label for="note">留一句话给自己</label><button data-action="delete-note" class="text-link">清空</button></div><textarea id="note" maxlength="2000" placeholder="下一件小事，是什么？">${esc(db.notes)}</textarea><small class="save-state" id="note-save">便笺仅保存在当前浏览器</small><button class="text-link" data-action="sound">${I('volume',16)} ${sound?'关闭合成风声':'开启合成风声'}</button></aside></div><div class="source-note">窗台场景 © 幡幡 / TangfanOVO，沿用 haiz 改编版本 · AGPL-3.0 <a href="room/source.html">原作、许可与完整对应源码 ↗</a></div></main>`}
function campusNav(active,teacher=true){return `<nav class="workspace-nav" aria-label="工作台导航">${(teacher?[['desk','今天','sun'],['lesson','课前准备','book'],['activities','活动协作','star']]:[['club','发现','star'],['constellation','社团星图','box'],['works','我的创作','edit']]).map(([r,l,i])=>`<a href="#${r}" ${active===r?'aria-current="page"':''}>${I(i,18)} ${l}</a>`).join('')}<span>${teacher?'HAIZ DESK':'HAIZ CLUB'} / 本机演示</span></nav>`}
function desk(){return `<main id="main" class="campus-page">${campusNav('desk')}<div class="desk-greeting"><div>${small('LESS BUSYWORK, MORE TEACHING')}<h1>下午好，老师<span>。</span></h1><p>让教学回归人，把琐事轻轻放下。</p></div><div class="day-label"><span>DEMO DAY</span><b>星期二</b><small>手动课程 · 演示数据</small></div></div><div class="desk-grid"><section class="lesson-card"><div class="card-eyebrow"><span>${I('clock',16)} 下一节课 · 示例安排</span><span class="badge">手动录入</span></div><div class="lesson-main"><div><span class="muted">高一语文 / 第三节</span><h2>${esc(db.lessonTitle)}</h2><p>${esc(db.lessonTime)} <span>·</span> 本地示例教案</p></div><div class="lesson-illustration">${I('book',80)}<span>一堂好课<br>从容开始</span></div></div><div class="lesson-bottom"><span>上次留下的重点<br><strong>${esc(db.lessonNote)}</strong></span><a href="#lesson" class="btn primary">打开课前卡 ${arrow()}</a></div></section><section class="panel todos"><div class="section-heading"><h2>今天的工作</h2><span class="muted" id="todo-count">${db.todos.filter(Boolean).length} / 3</span></div>${['整理下一节课的例证素材','查看社团作品审核','给明天留一条提醒'].map((t,i)=>`<label class="todo ${db.todos[i]?'done':''}"><input type="checkbox" data-todo="${i}" ${db.todos[i]?'checked':''}><span>${t}<small>${['课前准备','社团协作','个人清单'][i]}</small></span></label>`).join('')}<p class="quiet-note">不必全部完成。今天就到这里，也很好。</p></section><section class="quick-section"><div class="section-heading"><h2>随手收纳</h2><span class="muted">先记下来，稍后整理。</span></div><div class="quick-grid"><button data-action="capture">${I('edit',25)}<strong>一条便笺</strong><span>记下忽然想到的事</span>${arrow()}</button><button data-action="draft">${I('plus',25)}<strong>活动草稿</strong><span>用一张卡，把事情说清</span>${arrow()}</button><button data-action="materials">${I('folder',25)}<strong>资料匣</strong><span>最近使用的课前材料</span>${arrow()}</button></div></section><section class="panel collab"><div class="section-heading"><h2>社团协作</h2><a href="#activities" class="text-link">查看 ${arrow()}</a></div><div class="collab-icon">${I('star',30)}</div><h3>把创作，接力下去。</h3><p>${db.works.filter(w=>w.state==='submitted').length} 件演示作品等待指导教师审核</p><a href="#activities" class="text-link">进入一页活动 →</a></section></div><div class="demo-footnote">${I('shield',16)} 教师角色仅为演示切换，不代表身份认证。课程、活动、便笺只保存在本机。</div></main>`}
function lesson(){return `<main id="main" class="campus-page">${campusNav('lesson')}<div class="page-top"><div>${small('THIRTY SECONDS BEFORE CLASS')}<h1>课前 30 秒。</h1><p class="muted">打开需要的材料，就可以开始了。</p></div>${btn('编辑课程','edit-lesson','outline','edit')}</div><div class="lesson-detail"><section class="panel"><span class="badge">高一语文 · 手动示例</span><h2>${esc(db.lessonTitle)}</h2><p>${esc(db.lessonTime)} · 无正式课表接入</p><div class="lesson-outline"><span>01</span><div><h3>从一个问题开始</h3><p>「有道理」和「有证据」，是一回事吗？</p></div></div><div class="lesson-outline"><span>02</span><div><h3>辨认观点与论据</h3><p>选择生活中的例子，尝试把观点、论据和解释连接起来。</p></div></div><div class="lesson-outline"><span>03</span><div><h3>留给讨论的五分钟</h3><p>同一个论据能否支持不同观点？哪些条件需要说清楚？</p></div></div>${btn('打开示例课件','material','primary','book')}</section><aside><section class="panel"><h2>上次课留下的重点</h2><textarea id="lesson-note" maxlength="1500">${esc(db.lessonNote)}</textarea><small class="save-state">编辑后自动保存在本机</small></section><section class="panel"><h2>下课之后</h2><p>把想留给下一次的事记下来，就可以安心结束今天。</p>${btn('写一条便笺','capture','outline','edit')}</section></aside></div></main>`}
function activities(){return `<main id="main" class="campus-page">${campusNav('activities')}<div class="page-top"><div>${small('ONE ACTIVITY, ONE SHARED PAGE')}<h1>一页活动。</h1><p class="muted">时间、材料与创作记录，都在同一处。</p></div>${btn('新建活动草稿','draft','primary','plus')}</div><div class="activity-grid"><section><div class="section-heading"><h2>活动草稿</h2><span class="badge">本地保存</span></div>${db.drafts.length?db.drafts.map(d=>`<article class="panel draft-card"><div><span class="badge">${d.state==='submitted'?'待审核 · 演示':'草稿'}</span><h3>${esc(d.title)}</h3><p>${esc(d.club)} · ${esc(d.date)||'时间待定'} · ${esc(d.place)||'地点待补充'}</p><p>${esc(d.description)}</p></div><div>${d.state==='draft'?btn('提交演示审核',`draft-submit:${d.id}`,'outline'):''}<button class="text-link" data-action="draft-edit:${d.id}">编辑</button><button class="text-link" data-action="draft-delete:${d.id}">删除</button></div></article>`).join(''):`<section class="empty-state">${I('folder',36)}<h3>好想法，可以先有一个名字。</h3><p>填写标题，就能保存第一张活动卡。</p>${btn('创建活动草稿','draft','outline','plus')}</section>`}<div class="section-heading"><h2>作品与活动记录</h2><span class="muted">${db.works.filter(w=>w.state==='submitted').length} 件待审核</span></div>${db.works.length?db.works.map(w=>workCard(w,'teacher')).join(''):`<section class="empty-state"><h3>这里等待第一件作品。</h3><p>前往学生工作台创作并提交，就能在这里体验审核。</p><a class="text-link" href="#works">去创建演示作品 ↗</a></section>`}</section><aside class="panel process-panel">${small('FROM AN IDEA TO A MEMORY')}<h2>一件作品的旅程</h2>${['学生完成活动与作品','教师审核活动记录','作者逐件选择公开','管理员审核展签','在校园里偶然相遇'].map((x,i)=>`<div class="process-step"><span>0${i+1}</span><p>${x}</p></div>`).join('')}<p class="quiet-note">此流程全部在本机模拟。演示审核不会对外发布内容。</p><a class="text-link" href="#moderation">进入模拟审核台 ${arrow()}</a></aside></div></main>`}
function club(){return `<main id="main" class="campus-page club-page">${campusNav('club',false)}<section class="club-hero"><img src="assets/campus.webp" alt="日落校园概念美术"><div></div><article>${small('FIND YOUR PEOPLE, MAKE YOUR WORLD')}<h1>课表之外，<br>还有整个世界。</h1><p>让一个人的好奇，变成一群人的创造。</p><a class="btn cream" href="#constellation">探索社团星图 ${I('star',17)}</a></article><span>HAIZ CLUB<br><small>兴趣不必孤独。</small></span></section><div class="section-heading"><div>${small('A LITTLE CURIOSITY GOES A LONG WAY')}<h2>找到你的同频。</h2></div><a href="#constellation" class="text-link">社团星图 ${arrow()}</a></div><div class="filter-row"><div class="segmented filters">${['全部','科学','艺术','人文'].map(f=>`<button data-action="filter:${f}" aria-pressed="${filter===f}">${f}</button>`).join('')}</div><label class="search-box">${I('search',18)}<input id="club-search" placeholder="搜索社团或兴趣" value="${esc(search)}" aria-label="搜索社团或兴趣"></label><span class="muted">均为虚构社团提案</span></div><div class="club-grid" id="club-results">${clubResults()}</div>${round2.publicActivities()}<section class="club-lower"><div><div class="section-heading"><h2>本周活动护照</h2><span class="badge">DEMO</span></div>${events.map(e=>`<button class="event-row" data-action="event:${e.id}"><span class="event-date">${e.date}</span><div><h3>${e.name}</h3><p>${e.club} · ${e.kind}</p></div><span class="event-status">${db.enrolled.includes(e.id)?(e.capacity?'已报名 · 演示':'已候补 · 演示'):e.approved?'查看活动':'创作提案'}</span>${arrow()}</button>`).join('')}</div><aside class="inspiration-card">${small('THE WEEKLY LITTLE PROMPT')}<span class="inspiration-star">✳</span><h2>给熟悉的校园，<br>写一封信。</h2><p>一张照片，一段文字，一小节旋律。<br>形式不限，也不必交作业。</p>${btn('收下这个灵感','inspiration','outline','plus')}</aside></section><section class="my-creations-banner"><div>${small('THINGS WE MAKE TOGETHER')}<h2>让热爱，留下一件作品。</h2><p>公开与否，由你决定。</p></div><a href="#works" class="btn primary">我的创作 ${arrow()}</a></section></main>`}
function clubResults(){const list=clubs.filter(c=>(filter==='全部'||c.type===filter)&&`${c.name}${c.desc}${c.count}`.includes(search));return list.length?list.map(c=>`<button class="club-card" data-action="club:${c.id}"><div class="club-cover ${c.cover}"><span class="voxel-icon">${I(c.icon,46)}</span><span class="cover-label">${c.type.toUpperCase()} / CLUB PROPOSAL</span></div><div class="club-card-body"><h3>${c.name} ${arrow()}</h3><p>${c.desc}</p><span>${c.count}</span></div></button>`).join(''):`<div class="empty-state"><h3>还没有找到这个兴趣。</h3><p>换个关键词，或看看全部社团。</p></div>`}
function constellation(){return `<main id="main" class="campus-page">${campusNav('constellation',false)}<div class="page-top"><div>${small('AN ATLAS OF CURIOSITY')}<h1>兴趣，终会相遇。</h1><p class="muted">每一颗星，都是一群人的可能。所有社团均为虚构提案。</p></div><a class="text-link" href="#club">以列表发现社团 ${arrow()}</a></div><section class="constellation"><svg class="star-lines" viewBox="0 0 1000 500" preserveAspectRatio="none" aria-hidden="true"><path d="M210 165 520 90 780 270 455 345 210 165M520 90 455 345M210 165 780 270"/></svg><span class="star-caption">HAIZ CLUB<br><em>连接你的好奇心。</em></span>${clubs.map((c,i)=>`<button class="star-node node-${i}" data-action="club:${c.id}"><span>${I(c.icon,30)}</span><strong>${c.name}</strong><small>${c.type} · 概念社团</small></button>`).join('')}<span class="constellation-note">可用 Tab 切换社团 · Enter 查看详情</span></section><section class="relay"><div>${small('PASS IT ON')}<h2>给下一届，留一点光。</h2><p>从一份活动记录开始，让经验不随毕业消失。</p></div>${btn('打开社团接力模板','relay','outline','folder')}</section></main>`}
function workCard(w,role='student'){return `<article class="panel work-card" data-work-id="${esc(w.id)}"><div class="section-heading"><span class="badge">${states[w.state]||'未知状态'}</span><span class="muted">本机 DEMO</span></div><h3>${esc(w.title)}</h3><p class="work-body">${esc(w.body)}</p><small>活动记录：${esc(w.record||'暂无')} · ${w.completed?'演示活动已完成':'待完成'}</small><div class="work-actions">${role==='student'?`${['draft','returned','withdrawn'].includes(w.state)?btn('提交教师审核',`work:submit:${w.id}`,'primary'):''}${w.state==='teacher_approved'?btn('选择公开范围',`consent:${w.id}`,'primary'):''}${!['draft','withdrawn'].includes(w.state)?btn('撤回作品',`work:withdraw:${w.id}`,'outline'):''}${btn('删除',`work-delete:${w.id}`,'text-link')}`:''}${role==='teacher'&&w.state==='submitted'?`${btn('通过记录与作品',`work:approve:${w.id}`,'primary')}${btn('退回修改',`work:return:${w.id}`,'outline')}`:''}${role==='moderator'&&w.state==='public_requested'?btn('审核通过 · 展示展签',`work:publish:${w.id}`,'primary'):''}${role==='moderator'&&w.state==='published'?btn('下架展签',`work:remove:${w.id}`,'outline'):''}</div></article>`}
function works(){return `<main id="main" class="campus-page">${campusNav('works',false)}<div class="page-top"><div>${small('YOUR WORK, YOUR CHOICE')}<h1>把热爱，留在这里。</h1><p class="muted">作品默认私有。只有你逐件同意并通过双重审核，才会出现在本机校园展览。</p></div>${btn('新建一件作品','new-work','primary','plus')}</div><div class="works-layout"><section>${db.works.length?db.works.map(w=>workCard(w)).join(''):`<div class="empty-state large-empty">${I('edit',48)}<h2>第一件作品，不必完美。</h2><p>试着记录一束光，写下一个想法。</p>${btn('开始创作','new-work','primary','plus')}</div>`}</section><aside class="panel"><span class="badge">创作小贴士</span><h2>让作品有来处。</h2><p>记下活动经过、内容来源和你的观察。不填写真实姓名、班级或联系方式。</p><div class="divider"></div><h3>你的选择始终有效</h3><p>随时撤回或删除，校园展签会同步消失。</p><a href="#desk" class="text-link">切换教师演示 ${arrow()}</a></aside></div></main>`}
function moderation(){return `<main id="main" class="campus-page"><div class="demo-banner">${I('shield')} 隔离模拟审核台 · 不具备真实管理权限 · 不对外发布</div><div class="page-top"><div>${small('THE FINAL REVIEW')}<h1>让公开，经过认真选择。</h1></div><a href="#club" class="text-link">返回学生工作台 ${arrow()}</a></div>${db.works.filter(w=>['public_requested','published'].includes(w.state)).map(w=>workCard(w,'moderator')).join('')||'<div class="empty-state"><h2>暂时没有待公开作品。</h2><p>作品需先完成教师审核，再由作者明确同意公开。</p></div>'}<section class="panel"><h2>本机演示审计记录</h2>${db.audit.length?`<ol class="audit-list">${db.audit.slice(-20).reverse().map(a=>`<li><span>${esc(a.message)}</span><time>${new Date(a.at).toLocaleString('zh-CN')}</time></li>`).join('')}</ol>`:'<p class="muted">操作记录会出现在这里。此日志可被本机修改，不是生产审计日志。</p>'}</section></main>`}
function memory(){return `<main id="main" class="memory-page"><div class="page-top"><div>${small('THE CAMPUS REMEMBERS')}<h1>风景里，藏着时间。</h1><p class="muted">实拍与概念分开展示。资料沿用原仓库，年代与转载授权仍待独立核实。</p></div><a href="../journal.html" class="text-link">阅读原校园杂志 ${arrow()}</a></div>${places.map(p=>`<article class="memory-row"><img src="${p.photo}" alt="原仓库留存的${p.name}参考影像，具体来源状态见详情" loading="lazy"><div>${small(p.number+' / '+p.en)}<h2>${p.name}</h2><p>${p.body}</p><div class="row-actions">${btn('查看来源与故事',`place:${p.id}`,'outline')}<a class="text-link" href="#walk?place=${p.id}">去这里停留 ${arrow()}</a></div></div></article>`).join('')}<section class="archive-links"><h2>旧故事，仍然在这里。</h2>${[['../news.html','新闻档案'],['../director.html','探索导演台'],['../darkroom.html','共感暗房'],['../descent.html','从星球到树荫']].map(([u,t])=>`<a href="${u}">${t} ${arrow()}</a>`).join('')}</section></main>`}
const round2=createRound2({esc,I,modal,close,toast,download,render});
const pages={world,walk,garden,atlas,windowsill,desk,lesson,activities,club,constellation,works,moderation,memory,...Object.fromEntries(round2.routes.map(r=>[r,()=>round2.render(r)]))};
function render(){round2.leave();sceneSession++;scene?.dispose();scene=null;stopSound();const hash=location.hash.slice(1).split('?')[0];route=pages[hash]?hash:'world';document.body.dataset.page=route;$('#app').innerHTML=header()+pages[route]()+footer();document.title=`${{world:'校园世界',walk:'完整校园漫游',garden:'体素庭院',atlas:'全校地图',study:'思路续接',windowsill:'课间窗台',shelf:'思考书架',paper:'纸笔学习卡',resources:'公共学习资源',classroom:'教室公共屏',homework:'教师作业工作台',assignments:'今日作业',teach:'教师轻量发布',desk:'教师工作台',lesson:'课前准备',activities:'一页活动',club:'社团与创作',constellation:'社团星图',works:'我的创作',moderation:'模拟审核台',memory:'校园记忆'}[route]} · HAIZ WORLD`;updateTimer();if(route==='garden')loadScene();if(route==='atlas')$('#atlas-search').addEventListener('input',e=>{atlasSearch=e.target.value;atlasUpdate()});if(route==='windowsill')initNote();if(round2.routes.includes(route))round2.mount();if(route==='lesson')$('#lesson-note').addEventListener('input',e=>{db.lessonNote=e.target.value;save()});if(route==='club')$('#club-search').addEventListener('input',e=>{search=e.target.value;$('#club-results').innerHTML=clubResults()});}
async function loadScene(){const session=sceneSession;try{const {createWorld}=await import('./world3d.js');if(session!==sceneSession)return;const loaded=await createWorld($('#canvas-host'),{...db.prefs,onStatus:s=>{if(session===sceneSession&&$('#render-status'))$('#render-status').textContent=s}});if(session!==sceneSession){loaded.dispose();return}scene=loaded;const id=new URLSearchParams(location.hash.split('?')[1]).get('place');if(id)goTo(id)}catch{if(session!==sceneSession)return;if($('#render-status'))$('#render-status').textContent='静态风景 · 3D 暂不可用';toast('当前设备未能开启 3D，地点故事和静态风景仍可浏览。')}}
function goTo(id){const p=places.find(p=>p.id===id);if(!p)return;scene?.goto(id);if($('#location-name'))$('#location-name').textContent=p.name;history.replaceState(null,'',`#garden?place=${id}`);toast(`已到达概念地点：${p.name}`)}
function modal(title,body,wide=false){const d=$('#dialog');d.innerHTML=`<div class="dialog-top"><span class="eyebrow">HAIZ WORLD / DEMO</span><button class="icon-btn" data-action="close" aria-label="关闭对话框">${I('close')}</button></div><h2 id="dialog-title">${title}</h2>${body}`;d.classList.toggle('wide',wide);if(!d.open)d.showModal()}
function close(){ $('#dialog').close() }
function audit(message){db.audit.push({id:crypto.randomUUID(),at:new Date().toISOString(),message});db.audit=db.audit.slice(-100)}
function workAction(action,id){const w=db.works.find(x=>x.id===id);if(!w)return;const role=route==='moderation'?'moderator':['desk','activities'].includes(route)?'teacher':'student';try{const next=transition(w,action,role);db.works=db.works.map(x=>x.id===id?next:x);audit(`${states[next.state]}：${w.title}`);save();close();render();toast(`作品${states[next.state]}。仅在本机生效。`)}catch(e){toast(e.message)}}
function formError(message){const error=$('#form-error');if(error)error.textContent=message;else toast(message)}
function draftForm(id){const d=db.drafts.find(x=>x.id===id)||{};modal(d.id?'继续完善活动卡':'好想法，先记下来。',`<form id="draft-form" data-id="${esc(d.id||'')}"><label>活动标题 <input name="title" required maxlength="80" placeholder="例如：寻找校园的另一种光" value="${esc(d.title||'')}"></label><div class="form-columns"><label>承办社团<input name="club" maxlength="60" value="${esc(d.club||'概念摄影社')}"></label><label>演示时间<input name="date" type="datetime-local" value="${esc(d.date||'')}"></label></div><label>演示地点<input name="place" maxlength="100" placeholder="稍后补充" value="${esc(d.place||'')}"></label><label>想一起做什么？<textarea name="description" maxlength="1000" placeholder="目标、材料、注意事项……">${esc(d.description||'')}</textarea></label><p class="muted">只填标题即可保存。这里没有真实报名或通知。</p><p id="form-error" role="alert"></p><button class="btn primary" type="submit">保存活动草稿 ${I('check',18)}</button></form>`)}
function newWork(){modal('留下一件小小的作品。',`<form id="work-form"><label>作品标题<input name="title" required maxlength="80" placeholder="例如：树影来信"></label><label>作品内容<textarea name="body" required maxlength="1500" placeholder="写下一段原创文字，或描述你的创作。请勿填写真实个人信息。"></textarea></label><label>活动与来源记录<textarea name="record" required maxlength="500" placeholder="在什么演示活动里完成？素材来自哪里？"></textarea></label><label class="checkbox-label"><input type="checkbox" name="completed" required>我确认这次演示活动已完成，内容为原创或已获授权</label><p class="muted">保存后默认私有，可再提交教师审核。</p><p id="form-error" role="alert"></p><button class="btn primary" type="submit">保存私有作品</button></form>`)}
function showPlace(id){const p=places.find(x=>x.id===id);if(!p)return;modal(p.name,`<img class="dialog-photo" src="${p.photo}" alt="${p.name}原仓库参考影像"><span class="eyebrow">原仓库影像 · 非生成概念美术</span><p>${p.body}</p><p class="source-note">实拍来源归原作者与发布机构；照片年代、对应树种与转载授权待独立核实。<a href="${p.source}">查看原始来源记录 ↗</a></p><div class="row-actions"><a class="btn primary" href="#walk?place=${p.id}" data-action="close">去此处停留 ${arrow()}</a><button class="btn outline" data-action="share:${p.id}">复制地点链接</button><a class="text-link" href="${p.old}">原有资料入口 ↗</a></div>`)}
function showEvent(id){const e=events.find(x=>x.id===id);if(!e)return;const joined=db.enrolled.includes(id);modal(e.name,`<span class="badge">${e.approved?'模拟审批通过 · 仅演示':'创作提案 · 未审核'}</span><p>${e.desc}</p><dl class="event-details"><div><dt>承办</dt><dd>${e.club}（虚构）</dd></div><div><dt>安排</dt><dd>${e.time}</dd></div><div><dt>地点</dt><dd>${e.place}</dd></div><div><dt>容量</dt><dd>${e.capacity} 个演示名额 · 非真实人数</dd></div></dl><p class="muted">你的${e.capacity?'报名':'候补'}只写入当前浏览器，可随时取消，不会发送通知或建立正式名单。</p>${e.approved?btn(joined?'取消'+(e.capacity?'报名':'候补'):e.capacity?'演示报名':'加入演示候补',`enroll:${e.id}`,'primary'):btn('提案尚未审核','noop','outline')}<a href="#works" data-action="close" class="text-link block-link">活动之后，留下一件作品 ↗</a>`)}
function map(){modal('把整座校园，重新展开。',`<p>完整校园包含 34 个节点与 16 间开放的想象教室。选择一种走法：</p><div class="campus-entry-options"><a class="btn primary" href="#walk" data-action="close">第一人称走进校园 ↗</a><a class="btn outline" href="#atlas" data-action="close">展开全校地图 ↗</a><a class="text-link" href="#garden" data-action="close">体素庭院 · 三处概念小景 ↗</a></div><p class="muted">校园轮廓沿用原项目资料。建筑与室内为近似创作，地图不能作为实地导航。</p>`,true)}

function initNote(){const n=$('#note');n.addEventListener('input',()=>{db.notes=n.value;$('#note-save').textContent=save()?'已保存在当前浏览器':'保存受限 · 请导出备份'})}
function updateTimer(){const left=timerRemaining(db.timer);$$('[data-timer]').forEach(e=>e.textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`);const b=$('[data-action="timer"]');if(b)b.innerHTML=I(db.timer.end?'pause':'play',18)+(db.timer.end?'暂停专注':left?'开始专注':'再来一段');if($('#timer-state'))$('#timer-state').textContent=db.timer.end?'把注意力放回眼前。':'给自己一点不被打扰的时间';if(db.timer.end&&left===0){db.timer.end=null;db.timer.remaining=0;save();toast('这段专注完成了，休息一会儿吧。')}}
function stopSound(){if(sound){sound.close().catch(()=>{});sound=null}}
async function toggleSound(){if(sound){stopSound();toast('声音已关闭')}else{try{const A=window.AudioContext||window.webkitAudioContext;if(!A)throw Error();sound=new A();const buffer=sound.createBuffer(1,sound.sampleRate*3,sound.sampleRate);const data=buffer.getChannelData(0);let brown=0;for(let i=0;i<data.length;i++){brown=(brown+(Math.random()*2-1)*0.02)/1.02;data[i]=brown*2}const source=sound.createBufferSource();source.buffer=buffer;source.loop=true;const gain=sound.createGain();gain.gain.value=.15;source.connect(gain).connect(sound.destination);source.start();await sound.resume();toast('合成风声已开启 · 非校园现场录音')}catch{stopSound();toast('此浏览器暂不支持声音')}}$$('[data-action="sound"]').forEach(b=>{b.setAttribute('aria-pressed',String(!!sound));b.innerHTML=I(sound?'volume':'mute',17)+(sound?' 关闭合成风声':' 听一会儿风')})}
function exportData(){download(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),'haiz-local-demo.json')}
function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
async function action(a,el){const [kind,id,extra]=a.split(':');switch(kind){
case 'atlas-filter':atlasFilter=id;atlasUpdate();break;case 'atlas-place':if(CAMPUS_NODES.some(p=>p.id===id)){atlasSelected=id;atlasUpdate()}break;
case 'campus-fullscreen':try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#full-campus').requestFullscreen()}catch{toast('可使用独立窗口打开校园。')}break;
case 'close':close();break;
case 'mood':db.prefs.mood=id;save();$$('[data-mood]').forEach(e=>e.dataset.mood=id);$$('[data-action^="mood:"]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.action===a)));scene?.setMood(id);if($('.weather-name'))$('.weather-name').textContent={morning:'清晨时分',shade:'午后树影',rain:'雨后的光',sunset:'日落时分'}[id];break;
case 'place':showPlace(id);break;case 'map':map();break;case 'goto':goTo(id);break;
case 'map-goto':close();if(route==='garden')goTo(id);else location.hash=`walk?place=${id}`;break;
case 'walkmode':scene?.setAuto(id==='view');$$('[data-action^="walkmode:"]').forEach(b=>b.setAttribute('aria-pressed',String(b===el)));break;
case 'pause':if(scene){const paused=scene.togglePause();el.setAttribute('aria-pressed',String(paused));el.innerHTML=I(paused?'play':'pause',16)+(paused?' 继续动态':' 暂停动态')}break;
case 'static':sceneSession++;scene?.dispose();scene=null;$('#render-status').textContent='静态风景 · 低耗电';toast('已切换静态画面。重新进入漫游可恢复 3D。');break;
case 'snapshot':if(scene)scene.snapshot();else toast('当前是静态风景。进入 3D 后可导出实际渲染截图。');break;
case 'bookmark':if(scene){db.bookmarks.unshift({id:crypto.randomUUID(),...scene.cameraState()});db.bookmarks=db.bookmarks.slice(0,8);save();toast('机位已保存到当前浏览器')}else toast('请先开启 3D 场景');break;
case 'bookmarks':modal('收藏的观察位置',db.bookmarks.length?db.bookmarks.map((b,i)=>`<div class="bookmark-row"><span>机位 ${i+1}</span>${btn('恢复',`restore:${b.id}`,'outline')}${btn('删除',`delete-bookmark:${b.id}`,'text-link')}</div>`).join(''):'<p>还没有机位。在 3D 场景中点击定位图标即可保存。</p>');break;
case 'restore':if(scene){scene.restore(db.bookmarks.find(x=>x.id===id));close()}else toast('请先开启 3D 场景');break;
case 'delete-bookmark':db.bookmarks=db.bookmarks.filter(x=>x.id!==id);save();action('bookmarks');break;
case 'timer':db.timer=timerToggle(db.timer);save();updateTimer();break;
case 'timer-reset':db.timer={duration:db.timer.duration,remaining:db.timer.duration,end:null};save();updateTimer();break;
case 'duration':db.timer={duration:Number(id),remaining:Number(id),end:null};save();$$('[data-action^="duration:"]').forEach(b=>b.setAttribute('aria-pressed',String(b===el)));updateTimer();break;
case 'delete-note':db.notes='';save();if($('#note'))$('#note').value='';toast('便笺已清空');break;
case 'sound':await toggleSound();break;
case 'room-mood':$('.study-view').dataset.roomMood=id==='dusk'?'dusk':'night';$$('[data-action^="room-mood:"]').forEach(b=>b.setAttribute('aria-pressed',String(b===el)));$('#room-frame iframe')?.contentWindow.postMessage({channel:'haiz:windowsill:v1',type:'preset',id},location.origin);break;
case 'room-pause':{const paused=el.getAttribute('aria-pressed')!=='true';el.setAttribute('aria-pressed',String(paused));el.textContent=paused?'继续':'暂停';$('#room-frame iframe')?.contentWindow.postMessage({channel:'haiz:windowsill:v1',type:'pause',value:paused},location.origin);break}
case 'room':$('#room-frame').innerHTML='<iframe title="独立课间窗台场景，AGPL-3.0" src="room/scene/index.html?quality=low" allow="fullscreen"></iframe>';el.hidden=true;$('#room-loading').hidden=false;break;
case 'room-back':$('#room-frame').innerHTML='';$('#room-loading').hidden=true;$('.study-enter').hidden=false;break;
case 'capture':modal('先记下来。',`<form id="capture-form"><label>私人便笺<textarea name="note" maxlength="2000" placeholder="下节课要讲的、明天想做的……">${esc(db.notes)}</textarea></label><p class="muted">仅保存在本机，不上传到 AI 或其他服务。</p><button class="btn primary">保存便笺</button></form>`);break;
case 'draft':draftForm();break;case 'draft-edit':draftForm(id);break;
case 'draft-submit':{const d=db.drafts.find(x=>x.id===id);if(d){d.state='submitted';audit('活动提交演示审核：'+d.title);save();render();toast('已提交本机演示审核，不会发送通知。')}break}
case 'draft-delete':modal('删除这张活动草稿？',`<p>删除仅影响本机演示，无法撤销。</p>${btn('确认删除',`confirm-draft-delete:${id}`,'primary')}`);break;
case 'confirm-draft-delete':db.drafts=db.drafts.filter(x=>x.id!==id);save();close();render();break;
case 'edit-lesson':modal('编辑下一节课',`<form id="lesson-form"><label>课程主题<input name="title" maxlength="100" required value="${esc(db.lessonTitle)}"></label><label>手动时间<input name="time" maxlength="60" required value="${esc(db.lessonTime)}"></label><p class="muted">不连接学校课表。</p><button class="btn primary">保存课程</button></form>`);break;
case 'materials':modal('你的资料匣',`<p class="muted">示例材料 · 默认私有 · 无远程上传</p><button class="material-row" data-action="material">${I('book',28)}<span><strong>议论文：观点与论据</strong><small>原创演示教案 · v1</small></span>${arrow()}</button><a href="#lesson" data-action="close" class="text-link block-link">返回课前准备 ↗</a>`);break;
case 'material':modal('观点与论据 · 示例课件',`<span class="badge">原创教学示例 / v1</span><div class="slide-demo"><span>01 / THINK ABOUT IT</span><h3>「有道理」，<br>就有说服力吗？</h3><p>观点 → 论据 → 解释</p></div><p>讨论任务：从生活中选一个主张，找一个支持它的例子，再说清两者如何关联。</p><p class="source-note">此材料为本项目原创示例，不代表学校课程安排。</p>${btn('下载课件文本','download-material','primary','download')}`);break;
case 'download-material':download(new Blob(['HAIZ DESK 原创示例教案\n议论文中的逻辑结构\n\n1. 观点与论据有何区别？\n2. 选一个生活中的主张并提出证据。\n3. 解释证据与主张的关系。\n\n仅教学演示，不代表学校课程安排。'],{type:'text/plain;charset=utf-8'}),'课前示例教案.txt');break;
case 'filter':filter=id;$$('[data-action^="filter:"]').forEach(b=>b.setAttribute('aria-pressed',String(b===el)));$('#club-results').innerHTML=clubResults();break;
case 'club':{const c=clubs.find(x=>x.id===id);if(c)modal(c.name,`<div class="club-dialog-art ${c.cover}">${I(c.icon,64)}</div><span class="badge">虚构社团提案 · 非学校官方组织</span><p>${c.desc}</p><h3>这个学期，一起做</h3><p>${c.project}</p><p class="muted">指导教师待本人确认。此处没有正式社团身份或加入申请。</p>${btn('查看演示活动','event:'+({photo:'light',music:'sound',code:'build',literature:'light'}[id]),'primary')}<a href="#works" data-action="close" class="text-link block-link">留下自己的作品 ↗</a>`);break}
case 'event':showEvent(id);break;
case 'enroll':{const e=events.find(x=>x.id===id);try{db.enrolled=enroll(e,db.enrolled);save();const status=$(`[data-action="event:${id}"] .event-status`);if(status)status.textContent=db.enrolled.includes(id)?(e.capacity?'已报名 · 演示':'已候补 · 演示'):'查看活动';showEvent(id);toast(db.enrolled.includes(id)?(e.capacity?'演示报名已保存':'演示候补已保存'):'已取消')}catch(e){toast(e.message)}break}
case 'inspiration':db.notes=db.notes+(db.notes?'\n':'')+'灵感：给熟悉的校园写一封信。';db.notes=db.notes.slice(0,2000);save();toast('灵感已收进本机便笺，在课间窗台继续写。');break;
case 'relay':modal('把经验，留给下一届。',`<p>用这四个问题，整理一份社团接力档案。</p><ol class="relay-list"><li>我们完成了什么？保留作品与授权。</li><li>哪些准备最有帮助？记录流程与材料。</li><li>什么值得下次改进？给出具体例子。</li><li>谁可以继续使用？由作者和社团管理者确认。</li></ol>${btn('下载接力模板','relay-download','primary','download')}`);break;
case 'relay-download':download(new Blob(['社团接力档案（演示模板）\n\n项目名称：\n活动记录：\n作品及授权：\n准备流程：\n改进建议：\n允许使用范围：\n管理者审核：\n\n勿填写未授权个人信息。'],{type:'text/plain;charset=utf-8'}),'社团接力模板.txt');break;
case 'new-work':newWork();break;
case 'work':workAction(id,extra);break;
case 'consent':modal('由你决定，这件作品去哪里。',`<p>仅此作品会进入本机的概念校园展览。随时可以撤回，不会发布到公共网站。</p><form id="consent-form" data-id="${esc(id)}"><label class="checkbox-label"><input type="checkbox" required name="consent">我同意这件作品在本机校园展签中展示，并确认素材使用已获授权。</label><button class="btn primary">确认选择 · 交由管理员审核</button></form>`);break;
case 'work-delete':modal('删除这件作品？',`<p>本机作品与展签会同时删除，无法撤销。</p>${btn('确认删除',`confirm-work-delete:${id}`,'primary')}`);break;
case 'confirm-work-delete':db.works=db.works.filter(x=>x.id!==id);audit('作者删除一件演示作品');save();close();render();break;
case 'report':modal('举报演示展签',`<form id="report-form" data-id="${esc(id)}"><label>举报原因<textarea name="reason" required maxlength="500" placeholder="请描述需要核查的内容"></textarea></label><p>记录只进入本机模拟审核台，不会向任何人发送。</p><button class="btn primary">提交本机举报</button></form>`);break;
case 'share':try{await navigator.clipboard.writeText(location.href.split('#')[0]+`#garden?place=${id}`);toast('地点链接已复制')}catch{modal('地点链接',`<input readonly value="${esc(location.href.split('#')[0]+`#garden?place=${id}`)}" aria-label="可复制的地点链接"><p>长按或全选复制链接。</p>`)}break;
case 'install':if(installPrompt){await installPrompt.prompt();installPrompt=null}else modal('把校园，放在主屏幕。','<p>在支持的浏览器中打开此页面，使用浏览器菜单的「安装应用」或「添加到主屏幕」。</p><p>首次在线打开后，校园首页、工作台与本机工具可离线使用。完整旧校园与三维窗台仍需先加载。</p>');break;
case 'sources':modal('每个故事，都有来处。',`<p>本项目以原仓库 main（55638e8）为基础，完整保留旧站资源与来源说明。</p><ul class="source-list"><li>首页图像：为本项目生成的概念美术，非校园实拍。</li><li>体素小景：新增程序化几何，比例与布局为概念推演。</li><li>校园照片与历史资料：沿用原仓库，权利归原作者；年代与转载授权待核。</li><li>Three.js r128：MIT，<a href="assets/THREE-LICENSE.txt">许可全文</a>。</li><li>独立课间窗台：© 幡幡 / TangfanOVO，AGPL-3.0，<a href="room/source.html">完整源码与署名</a>。</li></ul><a class="text-link" href="../contact.html">原站来源与隐私说明 ↗</a>`,true);break;
case 'about':modal('一个可以慢慢生长的校园。',`<p>HAIZ WORLD 是非官方校园概念演示。公开世界无需注册；校内角色由你切换，用来试走完整流程。</p><div class="about-actions"><a href="#desk" data-action="close">教师演示 ${arrow()}</a><a href="#club" data-action="close">学生演示 ${arrow()}</a><a href="#moderation" data-action="close">模拟审核台 ${arrow()}</a></div><p class="muted">所有输入保存在当前浏览器，不上传、不通知、不连接学校账户。角色切换不提供真实权限。</p><div class="row-actions">${btn('导出本机数据','export','outline','download')}${btn('清除本机数据','reset-data','text-link')}</div>`);break;
case 'export':exportData();break;
case 'reset-data':modal('清除全部本机演示数据？',`<p>将删除便笺、课程、活动、作品、机位和计时进度。此操作无法撤销。</p>${btn('确认清除','confirm-reset','primary')}`);break;
case 'confirm-reset':db=empty();try{localStorage.removeItem(STORE)}catch{}close();render();toast('本机演示数据已清除');break;
}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el)action(el.dataset.action,el)});
document.addEventListener('change',e=>{if(e.target.matches('[data-todo]')){db.todos[Number(e.target.dataset.todo)]=e.target.checked;save();e.target.closest('.todo').classList.toggle('done',e.target.checked);$('#todo-count').textContent=`${db.todos.filter(Boolean).length} / 3`}if(e.target.id==='quality'){db.prefs.quality=e.target.value;save();scene?.setQuality(e.target.value)}});
document.addEventListener('submit',e=>{const f=e.target;if(!f.matches('#dialog form'))return;e.preventDefault();const d=new FormData(f);switch(f.id){case 'draft-form':{const title=String(d.get('title')).trim();if(!title)return formError('请填写活动标题');const id=f.dataset.id||crypto.randomUUID();const record={id,demo:true,title,club:String(d.get('club')),date:String(d.get('date')),place:String(d.get('place')),description:String(d.get('description')),state:'draft'};db.drafts=db.drafts.filter(x=>x.id!==id);db.drafts.unshift(record);save();close();if(route==='activities')render();toast('活动草稿已保存在本机');break}case 'work-form':{const title=String(d.get('title')).trim(),body=String(d.get('body')).trim(),record=String(d.get('record')).trim();if(!title||!body||!record)return formError('请完整填写作品与活动记录');db.works.unshift({id:crypto.randomUUID(),demo:true,title,body,record,completed:d.has('completed'),state:'draft',teacherApproved:false,consent:false});save();close();render();toast('作品已保存为私有草稿');break}case 'capture-form':db.notes=String(d.get('note'));save();close();toast('便笺已保存');break;case 'lesson-form':db.lessonTitle=String(d.get('title')).trim()||db.lessonTitle;db.lessonTime=String(d.get('time')).trim()||db.lessonTime;save();close();render();break;case 'consent-form':if(d.has('consent'))workAction('consent',f.dataset.id);break;case 'report-form':audit(`收到展签举报（${f.dataset.id}）：${String(d.get('reason')).slice(0,500)}`);save();close();toast('已进入本机模拟审核记录');break}});
window.addEventListener('message',e=>{const frame=$('#room-frame iframe');if(!frame||e.origin!==location.origin||e.source!==frame.contentWindow||e.data?.channel!=='haiz:windowsill:v1')return;const d=e.data;if(d.type==='ready'){$('#room-loading').hidden=true;const id=$('.study-view')?.dataset.roomMood==='dusk'?'dusk':'rainnight';frame.contentWindow.postMessage({channel:'haiz:windowsill:v1',type:'preset',id},location.origin);frame.contentWindow.postMessage({channel:'haiz:windowsill:v1',type:'quality',value:'low'},location.origin);frame.contentWindow.postMessage({channel:'haiz:windowsill:v1',type:'notes',value:[db.notes.slice(0,40)]},location.origin)}if(d.type==='error'){action('room-back');toast('当前设备未能运行窗台 3D，便笺与专注工具仍可使用。')}if(['action','focus'].includes(d.type)){if(['notes','space'].includes(d.key)){$('#note').focus();$('#note').scrollIntoView({block:'center',behavior:'smooth'})}if(d.key==='cal')$('.timer-ring').scrollIntoView({block:'center',behavior:'smooth'})}if(d.type==='action'){const links={phone:'../life.html',toys:'../darkroom.html',trips:'../director.html',maple:'room/source.html',where:'#walk',book:'room/index.html',letter:'room/index.html',music:'room/index.html'};if(Object.hasOwn(links,d.key))location.href=links[d.key];if(d.key==='jar')action('inspiration');if(d.key==='mug'){action('duration:300');$('.timer-ring').scrollIntoView({block:'center',behavior:'smooth'})}}});
window.addEventListener('hashchange',()=>{close();render();scrollTo(0,0);$('#main').setAttribute('tabindex','-1');$('#main').focus({preventScroll:true})});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
document.addEventListener('visibilitychange',()=>{if(document.hidden){sound?.suspend()}else{updateTimer();if(sound)sound.resume().catch(()=>{})}});
window.addEventListener('storage',e=>{if(e.key===STORE){try{db=validate(JSON.parse(e.newValue));render();toast('本机数据已与另一窗口同步')}catch{}}});
function connection(){ $('#network').hidden=navigator.onLine }window.addEventListener('online',connection);window.addEventListener('offline',connection);connection();
setInterval(updateTimer,1000);render();
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});

document.addEventListener('keydown',e=>{if(e.target.matches?.('.campus-node')&&['Enter',' '].includes(e.key)){e.preventDefault();action(e.target.dataset.action,e.target)}});
